-- 212: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 10.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_212_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_212_guard;
INSERT INTO _migration_212_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_037' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_8' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should variable cost per leather wallet be estimated for a planned production run?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Divide monthly rent alone by the selling price of one wallet","B. Subtract direct materials from revenue and call the balance variable cost","C. Add leather, lining, thread, hardware and unit packaging consumed by one wallet","D. Allocate the purchase cost of the main workshop tools directly to the first production run"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Variable unit cost follows the resources consumed by each wallet; fixed overhead and durable equipment are allocated separately when calculating total cost and price. Therefore the correct answer is C: Add leather, lining, thread, hardware and unit packaging consumed by one wallet.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_8' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_037' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_212_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_038' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_8' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which marketing action best tests demand for a new handmade leather-bag design in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Show a priced prototype to a defined customer segment and record orders, objections and preferred features","B. Ask workshop staff to judge the colour and shape before setting the production quantity","C. Produce a large stock before showing the design so buyers cannot influence it","D. Set the price from a competitor photograph without checking size, material or workmanship"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A priced prototype tested with intended buyers produces evidence about willingness to pay, use needs and objections before scarce leather and labour are committed to inventory. Therefore the correct answer is A: Show a priced prototype to a defined customer segment and record orders, objections and preferred features.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_038' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_212_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_039' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_8' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which response best addresses common leather-enterprise constraints in Ghana such as imported inputs, humid storage and inconsistent material supply?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Hold damp leather in sealed stacks to protect it from dust during the humid season","B. Qualify multiple suppliers, inspect incoming leather, control dry ventilated storage and price from current landed costs","C. Use one supplier without incoming inspection so colour remains associated with one source","D. Keep prices fixed from an old purchase even when exchange and transport costs change"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Supplier diversification, incoming quality checks, moisture control and current cost records reduce disruption, mould loss and margin erosion when local availability and imported-input costs vary. Therefore the correct answer is B: Qualify multiple suppliers, inspect incoming leather, control dry ventilated storage and price from current landed costs.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_039' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_212_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_040' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_8' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What combined check best supports quality and care before a leather bag is delivered?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Inspect seams, edges and hardware under load, then give care advice suited to the leather and finish","B. Inspect the lining appearance and defer structural testing until a sample is used","C. Apply a heavy conditioner before conducting a colourfastness test","D. Judge quality from surface shine and advise frequent soaking to maintain flexibility"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Delivery inspection should confirm structural and finish performance, while material-specific advice on cleaning, moisture, heat and conditioning helps the customer preserve the article safely. Therefore the correct answer is A: Inspect seams, edges and hardware under load, then give care advice suited to the leather and finish.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_040' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_037', 'topic_was_leatherwork_b004_8', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'How should variable cost per leather wallet be estimated for a planned production run?', 'multiple_choice', NULL, '["A. Divide monthly rent alone by the selling price of one wallet","B. Subtract direct materials from revenue and call the balance variable cost","C. Add leather, lining, thread, hardware and unit packaging consumed by one wallet","D. Allocate the purchase cost of the main workshop tools directly to the first production run"]', 'C', 'Variable unit cost follows the resources consumed by each wallet; fixed overhead and durable equipment are allocated separately when calculating total cost and price. Therefore the correct answer is C: Add leather, lining, thread, hardware and unit packaging consumed by one wallet.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_8', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_038', 'topic_was_leatherwork_b004_8', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Which marketing action best tests demand for a new handmade leather-bag design in Ghana?', 'multiple_choice', NULL, '["A. Show a priced prototype to a defined customer segment and record orders, objections and preferred features","B. Ask workshop staff to judge the colour and shape before setting the production quantity","C. Produce a large stock before showing the design so buyers cannot influence it","D. Set the price from a competitor photograph without checking size, material or workmanship"]', 'A', 'A priced prototype tested with intended buyers produces evidence about willingness to pay, use needs and objections before scarce leather and labour are committed to inventory. Therefore the correct answer is A: Show a priced prototype to a defined customer segment and record orders, objections and preferred features.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_8', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_039', 'topic_was_leatherwork_b004_8', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Which response best addresses common leather-enterprise constraints in Ghana such as imported inputs, humid storage and inconsistent material supply?', 'multiple_choice', NULL, '["A. Hold damp leather in sealed stacks to protect it from dust during the humid season","B. Qualify multiple suppliers, inspect incoming leather, control dry ventilated storage and price from current landed costs","C. Use one supplier without incoming inspection so colour remains associated with one source","D. Keep prices fixed from an old purchase even when exchange and transport costs change"]', 'B', 'Supplier diversification, incoming quality checks, moisture control and current cost records reduce disruption, mould loss and margin erosion when local availability and imported-input costs vary. Therefore the correct answer is B: Qualify multiple suppliers, inspect incoming leather, control dry ventilated storage and price from current landed costs.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_8', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_040', 'topic_was_leatherwork_b004_8', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What combined check best supports quality and care before a leather bag is delivered?', 'multiple_choice', NULL, '["A. Inspect seams, edges and hardware under load, then give care advice suited to the leather and finish","B. Inspect the lining appearance and defer structural testing until a sample is used","C. Apply a heavy conditioner before conducting a colourfastness test","D. Judge quality from surface shine and advise frequent soaking to maintain flexibility"]', 'A', 'Delivery inspection should confirm structural and finish performance, while material-specific advice on cleaning, moisture, heat and conditioning helps the customer preserve the article safely. Therefore the correct answer is A: Inspect seams, edges and hardware under load, then give care advice suited to the leather and finish.', 'easy', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_8', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_leatherwork_b004_037', 'q_was_leatherwork_b004_038', 'q_was_leatherwork_b004_039', 'q_was_leatherwork_b004_040');
